public class DatasetUtilities_iterateDomainBounds_TriageGen1Test {

    @Mock
    private XYDataset mockDataset;

    @Mock
    private IntervalXYDataset mockIntervalDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen1Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_IntervalIncludeInterval_WithValues() {
        // Setup mock for IntervalXYDataset
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalIncludeInterval_WithNaN() {
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        // X is NaN, Start is 5, End is NaN. Result should be 5 to 5.
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalIncludeInterval_EmptyDataset() {
        when(mockIntervalDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_StandardXY_IncludeIntervalFalse() {
        // Note: The logic for else block starts series loop from 1, not 0.
        // This is a specific behavior in the provided code.
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNotNull(result);
        assertEquals(20.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXY_WithNaN() {
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_StandardXY_MultipleItems() {
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(2);
        when(mockDataset.getXValue(1, 0)).thenReturn(10.0);
        when(mockDataset.getXValue(1, 1)).thenReturn(30.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNotNull(result);
        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(30.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXY_SeriesZeroSkipped() {
        // The code uses 'for (int series = 1; series < seriesCount; series++)' in the else block.
        // We test that series 0 is indeed ignored when includeInterval is false.
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        when(mockDataset.getXValue(0, 0)).thenReturn(1.0); // Should be ignored

        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalIncludeInterval_NonIntervalDataset() {
        // If includeInterval is true but dataset is NOT an instance of IntervalXYDataset,
        // it falls into the 'else' block.
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(100.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, true);

        assertNotNull(result);
        assertEquals(100.0, result.getLower(), 1e-9);
        assertEquals(100.0, result.getUpper(), 1e-9);
    }
}
